import{_ as t,o,c as r,a2 as i}from"./chunks/framework.D7WGirly.js";const p=JSON.parse('{"title":"Competitive Intelligence — Advanced Features & Customization","description":"","frontmatter":{},"headers":[],"relativePath":"competitive-intel-03-advanced-and-customization.md","filePath":"competitive-intel-03-advanced-and-customization.md"}'),a={name:"competitive-intel-03-advanced-and-customization.md"};function n(s,e,l,u,c,d){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="competitive-intelligence-—-advanced-features-customization" tabindex="-1">Competitive Intelligence — Advanced Features &amp; Customization <a class="header-anchor" href="#competitive-intelligence-—-advanced-features-customization" aria-label="Permalink to &quot;Competitive Intelligence — Advanced Features &amp; Customization&quot;">​</a></h1><p><em>Report scheduling, industry description strategy, and connecting intel to your planning workflow</em></p><hr><h2 id="choosing-your-report-frequency" tabindex="-1">Choosing Your Report Frequency <a class="header-anchor" href="#choosing-your-report-frequency" aria-label="Permalink to &quot;Choosing Your Report Frequency&quot;">​</a></h2><p>Lodestone supports two automatic report frequencies: <strong>Weekly</strong> and <strong>Biweekly</strong>.</p><table tabindex="0"><thead><tr><th>Frequency</th><th>Best for</th></tr></thead><tbody><tr><td>Weekly</td><td>Fast-moving markets, active competitors, teams that want fresh signal every week</td></tr><tr><td>Biweekly</td><td>Stable markets, lighter workload preference, teams reviewing reports in fortnightly planning cycles</td></tr></tbody></table><p>Weekly reporting gives you higher-frequency signal but requires more time to review. Biweekly is a lower-effort cadence that still keeps you meaningfully current without adding weekly overhead.</p><h3 id="choosing-the-right-day" tabindex="-1">Choosing the right day <a class="header-anchor" href="#choosing-the-right-day" aria-label="Permalink to &quot;Choosing the right day&quot;">​</a></h3><p>Set the day to align with when you&#39;re already reviewing product context — for example, the day before your weekly planning meeting or the morning of your strategy review. Receiving a report when you&#39;re already in planning mode means you&#39;re more likely to act on it.</p><hr><h2 id="getting-better-reports-from-your-industry-description" tabindex="-1">Getting Better Reports from Your Industry Description <a class="header-anchor" href="#getting-better-reports-from-your-industry-description" aria-label="Permalink to &quot;Getting Better Reports from Your Industry Description&quot;">​</a></h2><p>The industry description is the single most important input to report quality. The AI uses it to frame what &quot;competitive&quot; means for your context — which competitors to focus on, what market positioning looks like, and what signals are worth surfacing.</p><h3 id="what-to-include" tabindex="-1">What to include <a class="header-anchor" href="#what-to-include" aria-label="Permalink to &quot;What to include&quot;">​</a></h3><ul><li><strong>Market category</strong> — what category does your product sit in? (e.g. &quot;product management tools&quot;, &quot;revenue intelligence platforms&quot;, &quot;B2B sales enablement software&quot;)</li><li><strong>Customer type</strong> — who buys your product? (e.g. &quot;enterprise product teams&quot;, &quot;early-stage startups&quot;, &quot;mid-market SaaS companies&quot;)</li><li><strong>Key competitive dimensions</strong> — what do buyers in your market compare when evaluating options? (e.g. &quot;integration depth&quot;, &quot;AI features&quot;, &quot;ease of onboarding&quot;)</li></ul><h3 id="what-to-avoid" tabindex="-1">What to avoid <a class="header-anchor" href="#what-to-avoid" aria-label="Permalink to &quot;What to avoid&quot;">​</a></h3><ul><li>Generic descriptions (&quot;we build software for businesses&quot;) — these produce generic reports</li><li>Internal jargon — use market-standard terminology so the AI understands the competitive context</li><li>Overly long descriptions — two to four focused sentences outperform a lengthy paragraph</li></ul><hr><h2 id="using-the-ai-competitor-suggestion-feature" tabindex="-1">Using the AI Competitor Suggestion Feature <a class="header-anchor" href="#using-the-ai-competitor-suggestion-feature" aria-label="Permalink to &quot;Using the AI Competitor Suggestion Feature&quot;">​</a></h2><p>The AI suggestion feature is particularly useful when:</p><ul><li>You&#39;re setting up a new workspace and want a starting point</li><li>Your market has many players and you want to make sure you haven&#39;t missed anyone</li><li>You&#39;ve entered a new market segment and want to identify relevant competitors quickly</li></ul><p>Suggestions are generated from your industry description. If the suggestions feel irrelevant, revise your industry description to be more specific before retrying.</p><p>The suggestion UI lets you review each suggestion before adding it — select the ones that are genuinely competitive and skip the others. You can run suggestions again at any time; Lodestone will not re-add competitors already in your list.</p><hr><h2 id="building-a-report-to-backlog-workflow" tabindex="-1">Building a Report-to-Backlog Workflow <a class="header-anchor" href="#building-a-report-to-backlog-workflow" aria-label="Permalink to &quot;Building a Report-to-Backlog Workflow&quot;">​</a></h2><p>The most powerful use of Competitive Intelligence is connecting it to your planning cycle. A structured workflow looks like this:</p><ol><li><strong>Weekly report generates</strong> on your scheduled day</li><li><strong>Review the report</strong> — skim for significant moves by competitors</li><li><strong>Extract Features from Report</strong> — send the report to Extracts for AI analysis</li><li><strong>Review Extracts</strong> — evaluate the surfaced ideas. Add relevant ones to your backlog.</li><li><strong>Tag or annotate</strong> — use Feature tags to track which ideas came from competitive signals</li></ol><p>This process turns competitive awareness from a passive activity into an active input to your roadmap. Over time, your backlog will reflect not just internal ideas and customer requests but also competitive responses — and you&#39;ll have a visible record of where ideas came from.</p><hr><h2 id="interpreting-a-competitive-intelligence-report" tabindex="-1">Interpreting a Competitive Intelligence Report <a class="header-anchor" href="#interpreting-a-competitive-intelligence-report" aria-label="Permalink to &quot;Interpreting a Competitive Intelligence Report&quot;">​</a></h2><p>Reports are structured AI-generated documents that synthesize publicly available information about your competitors. A few things to keep in mind when reading them:</p><ul><li><strong>Reports describe observable activity</strong> — what competitors are shipping, announcing, and positioning publicly. They don&#39;t speculate about internal strategy.</li><li><strong>Reports are a starting point, not a conclusion</strong> — use them to surface signals worth investigating, not as authoritative analysis.</li><li><strong>Recency matters</strong> — a weekly report is more timely than a biweekly one. If a competitor moves fast, consider increasing your frequency.</li><li><strong>Quality depends on industry description</strong> — if a report feels off-target, revisit and sharpen your industry description before generating the next one.</li></ul><hr><h2 id="managing-a-large-competitor-list" tabindex="-1">Managing a Large Competitor List <a class="header-anchor" href="#managing-a-large-competitor-list" aria-label="Permalink to &quot;Managing a Large Competitor List&quot;">​</a></h2><p>There is no hard limit on how many competitors you can track, but report quality degrades as the list grows. Practical guidance:</p><ul><li><strong>Prioritize direct competitors</strong> — products that your prospects actively compare you against</li><li><strong>Include one or two aspirational benchmarks</strong> — market leaders you&#39;re likely to be measured against even if you don&#39;t compete directly</li><li><strong>Remove churned competitors</strong> — companies that have exited the market, pivoted, or are no longer relevant add noise</li><li><strong>Review the list quarterly</strong> — your competitive landscape changes; your tracker should reflect it</li></ul><hr><p><em>Next: Troubleshooting &amp; FAQs — common issues with report generation, AI suggestions, and extract extraction.</em></p>',37)])])}const h=t(a,[["render",n]]);export{p as __pageData,h as default};
